"""Markdown tables for VaR / CVaR from results/risk_accuracy.json (no hand-typed numbers).

Writes results/risk_summary.md. Run after experiments/risk_accuracy.py.
"""
import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
CL = ("mc", "sobol", "strat", "is", "tilt")
QU = ("q_certify", "q_matched", "q_varknown")


def fmt_q(v):
    return f"{v[0]:.2g}{'*' if v[1] else ''}"


def render(d) -> str:
    L = ["# VaR and CVaR results", "",
         "Generated by `experiments/risk_report.py` from `results/risk_accuracy.json`.", "",
         "## Exact three-year risk measures, two-country model (USD m)", "",
         "| scenario | E[L] | VaR95 | CVaR95 | VaR99 | CVaR99 | VaR99.5 | CVaR99.5 | CDF gap at 95 / 99 / 99.5 |",
         "|---|---:|---:|---:|---:|---:|---:|---:|---|"]
    for n, r in d["exact"]["scenarios"].items():
        g = r["cdf_gap"]
        L.append(f"| {n} | " + " | ".join(f"{r[k] / 1e6:.2f}" for k in
                 ("E[L]", "VaR95", "CVaR95", "VaR99", "CVaR99", "VaR99.5", "CVaR99.5"))
                 + f" | {g['95']:.1e} / {g['99']:.1e} / {g['99.5']:.1e} |")
    L += ["", "CDF gap = min over loss atoms of |F(l) - alpha|; VaR identification needs "
          "precision below it.", "",
          "## Exact risk measures, n-country chain (USD m; T = 40m x n)", "",
          "| n | E[L] | VaR95 | CVaR95 | VaR99 | CVaR99 | VaR99.5 | CVaR99.5 | support | seconds |",
          "|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|"]
    for n, r in d["exact"]["chain"].items():
        L.append(f"| {n} | " + " | ".join(f"{r[k] / 1e6:.2f}" for k in
                 ("E[L]", "VaR95", "CVaR95", "VaR99", "CVaR99", "VaR99.5", "CVaR99.5"))
                 + f" | {r['support_size']} | {r['seconds']:.2f} |")
    for tgt in ("0.01", "0.003", "0.001"):
        if not all(tgt in r["queries_needed"] for acc in d["accuracy"].values() for r in acc.values()):
            continue
        L += ["", f"## Queries to {float(tgt):.1%} relative RMSE on CVaR (* = extrapolated)", "",
              "| scenario | alpha | " + " | ".join(CL + QU) + " | quantum / best classical |",
              "|---|---|" + "---:|" * (len(CL) + len(QU) + 1)]
        for n, acc in d["accuracy"].items():
            for a, r in acc.items():
                row = r["queries_needed"][tgt]
                best_c = min(row[m][0] for m in CL)
                best_q = min(row[m][0] for m in ("q_certify", "q_matched"))
                L.append(f"| {n} | {a} | " + " | ".join(fmt_q(row[m]) for m in CL + QU)
                         + f" | {best_q / best_c:.2f} |")
    L += ["", "Ratio < 1 means the quantum route (best of certified / matched bisection, VaR "
          "stage included) needs fewer queries than the best classical estimator. "
          "`q_varknown` is a lower bound that assumes VaR is given. The tilted IS is tuned "
          "with the exact answer, so it is an optimistic classical baseline.",
          "", f"Replications: classical {d['reps']} (Sobol {d['reps_sobol']}), quantum "
          f"{d['reps_quantum']}; seed {d['seed']}."]
    return "\n".join(L) + "\n"


if __name__ == "__main__":
    fn = sys.argv[1] if len(sys.argv) > 1 else "risk_accuracy.json"
    md = render(json.loads((ROOT / "results" / fn).read_text()))
    (ROOT / "results" / "risk_summary.md").write_text(md, encoding="utf-8")
    print(md)
